-- Managed Quran game question bank.
create table if not exists public.game_questions (
  id text primary key,
  surah_number integer not null,
  surah_name text not null,
  ayah_number integer not null,
  full_ayah text not null,
  hidden_word text not null,
  options jsonb not null,
  correct_option text not null,
  difficulty text not null,
  level integer not null check (level between 1 and 100),
  recitation_audio text,
  global_ayah_number integer,
  explanation text,
  active boolean not null default true,
  updated_at timestamptz not null default now()
);

alter table public.game_questions enable row level security;
drop policy if exists game_questions_read on public.game_questions;
create policy game_questions_read
on public.game_questions
for select to authenticated
using (active = true or public.is_owner());

drop policy if exists game_questions_owner_write on public.game_questions;
create policy game_questions_owner_write
on public.game_questions
for all to authenticated
using (public.is_owner())
with check (public.is_owner());

grant select on public.game_questions to authenticated;
grant insert, update, delete on public.game_questions to authenticated;

create index if not exists game_questions_level_idx
  on public.game_questions(level, active);
create index if not exists game_questions_difficulty_idx
  on public.game_questions(difficulty, active);

