('30-34',30,'الروم',34,'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ ۚ فَتَمَتَّعُوا۟ فَسَوْفَ تَعْلَمُونَ','فَتَمَتَّعُوا۟','["أَشْيَآءَهُمْ","ءَاتَيْنَٰهُمُ","فَتَمَتَّعُوا۟","ءَاتَيْنَٰهُمْ"]'::jsonb,'فَتَمَتَّعُوا۟','medium',31,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3443.mp3',3443,NULL,TRUE),
('33-64',33,'الأحزاب',64,'إِنَّ ٱللَّهَ لَعَنَ ٱلْكَٰفِرِينَ وَأَعَدَّ لَهُمْ سَعِيرًا','ٱلْكَٰفِرِينَ','["أَبْصَٰرُهُمْ","ٱلْكَٰفِرِينَ","أَرْحَامَكُمْ","أَضْغَٰنَكُمْ"]'::jsonb,'ٱلْكَٰفِرِينَ','medium',31,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3597.mp3',3597,NULL,TRUE),
('36-39',36,'يس',39,'وَٱلْقَمَرَ قَدَّرْنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلْعُرْجُونِ ٱلْقَدِيمِ','حَتَّىٰ','["أَءِذَا","أَخَافُ","حَتَّىٰ","أَدْرِى"]'::jsonb,'حَتَّىٰ','medium',31,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3744.mp3',3744,NULL,TRUE),
('36-74',36,'يس',74,'وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةًۭ لَّعَلَّهُمْ يُنصَرُونَ','ٱللَّهِ','["ٱللَّهِ","أَخَافُ","أَدْرِى","أَءِذَا"]'::jsonb,'ٱللَّهِ','medium',31,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3779.mp3',3779,NULL,TRUE),
('37-21',37,'الصافات',21,'هَٰذَا يَوْمُ ٱلْفَصْلِ ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ','ٱلَّذِى','["ٱلَّذِى","أَدْرِى","أَخَافُ","أَءِذَا"]'::jsonb,'ٱلَّذِى','medium',31,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3809.mp3',3809,NULL,TRUE),
