('38-85',38,'ص',85,'لَأَمْلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنْهُمْ أَجْمَعِينَ','وَمِمَّن','["ءَايَٰتُ","وَمِمَّن","أَبْلُغُ","ءَايَٰتِ"]'::jsonb,'وَمِمَّن','medium',31,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4055.mp3',4055,NULL,TRUE),
('40-73',40,'غافر',73,'ثُمَّ قِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تُشْرِكُونَ','أَيْنَ','["أَتَىٰ","أَقُلْ","أَيْنَ","أَجْرٌ"]'::jsonb,'أَيْنَ','medium',31,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4206.mp3',4206,NULL,TRUE),
('43-16',43,'الزخرف',16,'أَمِ ٱتَّخَذَ مِمَّا يَخْلُقُ بَنَاتٍۢ وَأَصْفَىٰكُم بِٱلْبَنِينَ','يَخْلُقُ','["ءَايَٰتِ","ءَايَٰتُ","يَخْلُقُ","أَبْلُغُ"]'::jsonb,'يَخْلُقُ','medium',31,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4341.mp3',4341,NULL,TRUE),
('43-50',43,'الزخرف',50,'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلْعَذَابَ إِذَا هُمْ يَنكُثُونَ','ٱلْعَذَابَ','["ٱلْعَذَابَ","ءَامَنُوا۟","ءَالِهَةًۭ","ءَاتَيْنَا"]'::jsonb,'ٱلْعَذَابَ','medium',32,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4375.mp3',4375,NULL,TRUE),
('44-5',44,'الدخان',5,'أَمْرًۭا مِّنْ عِندِنَآ ۚ إِنَّا كُنَّا مُرْسِلِينَ','إِنَّا','["أَتَىٰ","أَقُلْ","إِنَّا","أَجْرٌ"]'::jsonb,'إِنَّا','medium',32,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4419.mp3',4419,NULL,TRUE),
('44-38',44,'الدخان',38,'وَمَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ','وَٱلْأَرْضَ','["وَٱلْأَرْضَ","ءَامَنُوٓا۟","ءَاسَفُونَا","ءَاتَىٰهُمْ"]'::jsonb,'وَٱلْأَرْضَ','medium',32,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4452.mp3',4452,NULL,TRUE),
('50-12',50,'ق',12,'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍۢ وَأَصْحَٰبُ ٱلرَّسِّ وَثَمُودُ','نُوحٍۢ','["نُوحٍۢ","أَجْرٌ","أَتَىٰ","أَقُلْ"]'::jsonb,'نُوحٍۢ','medium',32,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4642.mp3',4642,NULL,TRUE),
('51-40',51,'الذاريات',40,'فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِى ٱلْيَمِّ وَهُوَ مُلِيمٌۭ','فِى','["أَن","إِن","فِى","إِذ"]'::jsonb,'فِى','medium',32,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4715.mp3',4715,NULL,TRUE),
