('52-45',52,'الطور',45,'فَذَرْهُمْ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى فِيهِ يُصْعَقُونَ','يَوْمَهُمُ','["يَوْمَهُمُ","ءَالِهَةًۭ","ءَاتَيْنَا","ءَامَنُوا۟"]'::jsonb,'يَوْمَهُمُ','medium',32,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4780.mp3',4780,NULL,TRUE),
('54-17',54,'القمر',17,'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍۢ','لِلذِّكْرِ','["ءَالِهَةًۭ","ءَاتَيْنَا","ءَامَنُوا۟","لِلذِّكْرِ"]'::jsonb,'لِلذِّكْرِ','medium',32,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4863.mp3',4863,NULL,TRUE),
('56-1',56,'الواقعة',1,'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا وَقَعَتِ ٱلْوَاقِعَةُ','ٱلرَّحِيمِ','["ءَالِهَةًۭ","ٱلرَّحِيمِ","ءَامَنُوا۟","ءَاتَيْنَا"]'::jsonb,'ٱلرَّحِيمِ','medium',32,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4980.mp3',4980,NULL,TRUE),
('67-25',67,'الملك',25,'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ','ٱلْوَعْدُ','["ٱلْوَعْدُ","ءَايَٰتٍۭ","ءَاثَرَكَ","ءَامَنَّا"]'::jsonb,'ٱلْوَعْدُ','medium',32,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5266.mp3',5266,NULL,TRUE),
('69-11',69,'الحاقة',11,'إِنَّا لَمَّا طَغَا ٱلْمَآءُ حَمَلْنَٰكُمْ فِى ٱلْجَارِيَةِ','ٱلْمَآءُ','["ءَامَنَّا","ءَايَٰتٍۭ","ٱلْمَآءُ","ءَاثَرَكَ"]'::jsonb,'ٱلْمَآءُ','medium',33,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5334.mp3',5334,NULL,TRUE),
('71-9',71,'نوح',9,'ثُمَّ إِنِّىٓ أَعْلَنتُ لَهُمْ وَأَسْرَرْتُ لَهُمْ إِسْرَارًۭا','لَهُمْ','["أَقُلْ","لَهُمْ","أَتَىٰ","أَجْرٌ"]'::jsonb,'لَهُمْ','medium',33,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5428.mp3',5428,NULL,TRUE),
('73-18',73,'المزمل',18,'ٱلسَّمَآءُ مُنفَطِرٌۢ بِهِۦ ۚ كَانَ وَعْدُهُۥ مَفْعُولًا','كَانَ','["ءَالَ","أَقُل","كَانَ","أَنَّ"]'::jsonb,'كَانَ','medium',33,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5493.mp3',5493,NULL,TRUE),
