('81-1',81,'التكوير',1,'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا ٱلشَّمْسُ كُوِّرَتْ','ٱلرَّحِيمِ','["ءَاتَيْنَا","ٱلرَّحِيمِ","ءَالِهَةًۭ","ءَامَنُوا۟"]'::jsonb,'ٱلرَّحِيمِ','medium',33,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5801.mp3',5801,NULL,TRUE),
('84-1',84,'الانشقاق',1,'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ','ٱلرَّحِيمِ','["ءَاتَيْنَا","ءَامَنُوا۟","ٱلرَّحِيمِ","ءَالِهَةًۭ"]'::jsonb,'ٱلرَّحِيمِ','medium',33,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5885.mp3',5885,NULL,TRUE),
