('6-85',6,'الأنعام',85,'وَزَكَرِيَّا وَيَحْيَىٰ وَعِيسَىٰ وَإِلْيَاسَ ۖ كُلٌّۭ مِّنَ ٱلصَّٰلِحِينَ','وَإِلْيَاسَ','["وَإِلْيَاسَ","ءَامَنُوٓا۟","ءَاتَىٰهُمْ","ءَاسَفُونَا"]'::jsonb,'وَإِلْيَاسَ','medium',33,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/874.mp3',874,NULL,TRUE),
('7-104',7,'الأعراف',104,'وَقَالَ مُوسَىٰ يَٰفِرْعَوْنُ إِنِّى رَسُولٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ','رَسُولٌۭ','["رَسُولٌۭ","ءَايَٰتِ","أَبْلُغُ","ءَايَٰتُ"]'::jsonb,'رَسُولٌۭ','medium',34,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1058.mp3',1058,NULL,TRUE),
('8-21',8,'الأنفال',21,'وَلَا تَكُونُوا۟ كَٱلَّذِينَ قَالُوا۟ سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ','سَمِعْنَا','["سَمِعْنَا","ءَاثَرَكَ","ءَايَٰتٍۭ","ءَامَنَّا"]'::jsonb,'سَمِعْنَا','medium',34,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1181.mp3',1181,NULL,TRUE),
('11-55',11,'هود',55,'مِن دُونِهِۦ ۖ فَكِيدُونِى جَمِيعًۭا ثُمَّ لَا تُنظِرُونِ','جَمِيعًۭا','["ءَامَنَّا","ءَايَٰتٍۭ","ءَاثَرَكَ","جَمِيعًۭا"]'::jsonb,'جَمِيعًۭا','medium',34,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1528.mp3',1528,NULL,TRUE),
