('15-7',15,'الحجر',7,'لَّوْ مَا تَأْتِينَا بِٱلْمَلَٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ','إِن','["إِن","إِذ","بَل","أَن"]'::jsonb,'إِن','medium',34,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1809.mp3',1809,NULL,TRUE),
