('16-50',16,'النحل',50,'يَخَافُونَ رَبَّهُم مِّن فَوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ ۩','فَوْقِهِمْ','["فَوْقِهِمْ","ءَاتَيْنَا","ءَامَنُوا۟","ءَالِهَةًۭ"]'::jsonb,'فَوْقِهِمْ','medium',34,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1951.mp3',1951,NULL,TRUE),
('17-108',17,'الإسراء',108,'وَيَقُولُونَ سُبْحَٰنَ رَبِّنَآ إِن كَانَ وَعْدُ رَبِّنَا لَمَفْعُولًۭا','كَانَ','["أَنَّ","ءَالَ","كَانَ","أَقُل"]'::jsonb,'كَانَ','medium',34,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2137.mp3',2137,NULL,TRUE),
('18-72',18,'الكهف',72,'قَالَ أَلَمْ أَقُلْ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًۭا','لَن','["إِذ","إِن","أَن","لَن"]'::jsonb,'لَن','medium',34,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2212.mp3',2212,NULL,TRUE),
