('21-15',21,'الأنبياء',15,'فَمَا زَالَت تِّلْكَ دَعْوَىٰهُمْ حَتَّىٰ جَعَلْنَٰهُمْ حَصِيدًا خَٰمِدِينَ','حَتَّىٰ','["أَخَافُ","أَءِذَا","أَدْرِى","حَتَّىٰ"]'::jsonb,'حَتَّىٰ','medium',35,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2498.mp3',2498,NULL,TRUE),
