('33-47',33,'الأحزاب',47,'وَبَشِّرِ ٱلْمُؤْمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضْلًۭا كَبِيرًۭا','مِّنَ','["ءَالَ","مِّنَ","أَقُل","أَنَّ"]'::jsonb,'مِّنَ','medium',36,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3580.mp3',3580,NULL,TRUE),
