('43-81',43,'الزخرف',81,'قُلْ إِن كَانَ لِلرَّحْمَٰنِ وَلَدٌۭ فَأَنَا۠ أَوَّلُ ٱلْعَٰبِدِينَ','وَلَدٌۭ','["أَخَافُ","أَدْرِى","وَلَدٌۭ","أَءِذَا"]'::jsonb,'وَلَدٌۭ','medium',37,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4406.mp3',4406,NULL,TRUE),
