('50-28',50,'ق',28,'قَالَ لَا تَخْتَصِمُوا۟ لَدَىَّ وَقَدْ قَدَّمْتُ إِلَيْكُم بِٱلْوَعِيدِ','وَقَدْ','["وَقَدْ","أَقُلْ","أَجْرٌ","أَتَىٰ"]'::jsonb,'وَقَدْ','medium',37,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4658.mp3',4658,NULL,TRUE),
