('52-36',52,'الطور',36,'أَمْ خَلَقُوا۟ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۚ بَل لَّا يُوقِنُونَ','وَٱلْأَرْضَ','["وَٱلْأَرْضَ","ءَاسَفُونَا","ءَاتَىٰهُمْ","ءَامَنُوٓا۟"]'::jsonb,'وَٱلْأَرْضَ','medium',37,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4771.mp3',4771,NULL,TRUE),
('55-35',55,'الرحمن',35,'يُرْسَلُ عَلَيْكُمَا شُوَاظٌۭ مِّن نَّارٍۢ وَنُحَاسٌۭ فَلَا تَنتَصِرَانِ','نَّارٍۢ','["أَدْرِى","أَخَافُ","أَءِذَا","نَّارٍۢ"]'::jsonb,'نَّارٍۢ','medium',37,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4936.mp3',4936,NULL,TRUE),
('67-18',67,'الملك',18,'وَلَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ','قَبْلِهِمْ','["قَبْلِهِمْ","ءَاتَيْنَا","ءَامَنُوا۟","ءَالِهَةًۭ"]'::jsonb,'قَبْلِهِمْ','medium',38,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5259.mp3',5259,NULL,TRUE),
