('72-20',72,'الجن',20,'قُلْ إِنَّمَآ أَدْعُوا۟ رَبِّى وَلَآ أُشْرِكُ بِهِۦٓ أَحَدًۭا','وَلَآ','["أَقُلْ","أَجْرٌ","وَلَآ","أَتَىٰ"]'::jsonb,'وَلَآ','medium',38,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5467.mp3',5467,NULL,TRUE),
('76-5',76,'الإنسان',5,'إِنَّ ٱلْأَبْرَارَ يَشْرَبُونَ مِن كَأْسٍۢ كَانَ مِزَاجُهَا كَافُورًا','كَأْسٍۢ','["أَخَافُ","كَأْسٍۢ","أَءِذَا","أَدْرِى"]'::jsonb,'كَأْسٍۢ','medium',38,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5596.mp3',5596,NULL,TRUE),
('83-29',83,'المطففين',29,'إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ','مِنَ','["أَمِ","مِنَ","أَنِ","أَمْ"]'::jsonb,'مِنَ','medium',38,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5877.mp3',5877,NULL,TRUE),
('99-1',99,'الزلزلة',1,'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا','إِذَا','["أَقُل","إِذَا","ءَالَ","أَنَّ"]'::jsonb,'إِذَا','medium',38,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/6139.mp3',6139,NULL,TRUE),
