('18-81',18,'الكهف',81,'فَأَرَدْنَآ أَن يُبْدِلَهُمَا رَبُّهُمَا خَيْرًۭا مِّنْهُ زَكَوٰةًۭ وَأَقْرَبَ رُحْمًۭا','خَيْرًۭا','["ءَايَٰتُ","أَبْلُغُ","خَيْرًۭا","ءَايَٰتِ"]'::jsonb,'خَيْرًۭا','medium',40,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2221.mp3',2221,NULL,TRUE),
('19-36',19,'مريم',36,'وَإِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۚ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ','فَٱعْبُدُوهُ','["فَٱعْبُدُوهُ","ءَاذَانِهِمْ","أَرْسَلْنَآ","ءَاثَٰرِهِمْ"]'::jsonb,'فَٱعْبُدُوهُ','medium',40,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2286.mp3',2286,NULL,TRUE),
