('21-10',21,'الأنبياء',10,'لَقَدْ أَنزَلْنَآ إِلَيْكُمْ كِتَٰبًۭا فِيهِ ذِكْرُكُمْ ۖ أَفَلَا تَعْقِلُونَ','فِيهِ','["أَقُل","ءَالَ","فِيهِ","أَنَّ"]'::jsonb,'فِيهِ','medium',40,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2493.mp3',2493,NULL,TRUE),
('21-88',21,'الأنبياء',88,'فَٱسْتَجَبْنَا لَهُۥ وَنَجَّيْنَٰهُ مِنَ ٱلْغَمِّ ۚ وَكَذَٰلِكَ نُۨجِى ٱلْمُؤْمِنِينَ','ٱلْغَمِّ','["ءَايَٰتِ","ءَايَٰتُ","أَبْلُغُ","ٱلْغَمِّ"]'::jsonb,'ٱلْغَمِّ','medium',40,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2571.mp3',2571,NULL,TRUE),
('22-42',22,'الحج',42,'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍۢ وَعَادٌۭ وَثَمُودُ','قَبْلَهُمْ','["ءَالِهَةًۭ","ءَاتَيْنَا","ءَامَنُوا۟","قَبْلَهُمْ"]'::jsonb,'قَبْلَهُمْ','medium',40,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2637.mp3',2637,NULL,TRUE),
