('36-19',36,'يس',19,'قَالُوا۟ طَٰٓئِرُكُم مَّعَكُمْ ۚ أَئِن ذُكِّرْتُم ۚ بَلْ أَنتُمْ قَوْمٌۭ مُّسْرِفُونَ','ذُكِّرْتُم','["ءَاتَيْنَا","ءَامَنُوا۟","ذُكِّرْتُم","ءَالِهَةًۭ"]'::jsonb,'ذُكِّرْتُم','hard',51,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3724.mp3',3724,NULL,TRUE),
