('40-51',40,'غافر',51,'إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيَوْمَ يَقُومُ ٱلْأَشْهَٰدُ','فِى','["إِن","إِذ","فِى","أَن"]'::jsonb,'فِى','hard',52,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4184.mp3',4184,NULL,TRUE),
