('19-43',19,'مريم',43,'يَٰٓأَبَتِ إِنِّى قَدْ جَآءَنِى مِنَ ٱلْعِلْمِ مَا لَمْ يَأْتِكَ فَٱتَّبِعْنِىٓ أَهْدِكَ صِرَٰطًۭا سَوِيًّۭا','مَا','["مَا","أَن","إِن","إِذ"]'::jsonb,'مَا','hard',59,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2293.mp3',2293,NULL,TRUE),
('20-74',20,'طه',74,'إِنَّهُۥ مَن يَأْتِ رَبَّهُۥ مُجْرِمًۭا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ','لَهُۥ','["لَهُۥ","أَئِن","أَقُل","أَنتَ"]'::jsonb,'لَهُۥ','hard',60,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2422.mp3',2422,NULL,TRUE),
('21-41',21,'الأنبياء',41,'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍۢ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ','بِٱلَّذِينَ','["ءَايَٰتُهُۥ","ءَامَنُوٓا۟","ءَايَٰتِنَا","بِٱلَّذِينَ"]'::jsonb,'بِٱلَّذِينَ','hard',60,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2524.mp3',2524,NULL,TRUE),
('22-44',22,'الحج',44,'وَأَصْحَٰبُ مَدْيَنَ ۖ وَكُذِّبَ مُوسَىٰ فَأَمْلَيْتُ لِلْكَٰفِرِينَ ثُمَّ أَخَذْتُهُمْ ۖ فَكَيْفَ كَانَ نَكِيرِ','لِلْكَٰفِرِينَ','["أَبْلَغْتُكُمْ","أَشْيَآءَهُمْ","بِتَأْوِيلِهِۦ","لِلْكَٰفِرِينَ"]'::jsonb,'لِلْكَٰفِرِينَ','hard',60,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2639.mp3',2639,NULL,TRUE),
('24-34',24,'النور',34,'وَلَقَدْ أَنزَلْنَآ إِلَيْكُمْ ءَايَٰتٍۢ مُّبَيِّنَٰتٍۢ وَمَثَلًۭا مِّنَ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُمْ وَمَوْعِظَةًۭ لِّلْمُتَّقِينَ','مِّنَ','["أَقُل","مِّنَ","أَنتَ","أَئِن"]'::jsonb,'مِّنَ','hard',60,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2825.mp3',2825,NULL,TRUE),
('25-74',25,'الفرقان',74,'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعْيُنٍۢ وَٱجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا','أَزْوَٰجِنَا','["ءَاثَٰرِهِمْ","أَزْوَٰجِنَا","ءَاتَيْنَٰهُ","ءَاتَىٰهُمَا"]'::jsonb,'أَزْوَٰجِنَا','hard',60,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2929.mp3',2929,NULL,TRUE),
('27-59',27,'النمل',59,'قُلِ ٱلْحَمْدُ لِلَّهِ وَسَلَٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصْطَفَىٰٓ ۗ ءَآللَّهُ خَيْرٌ أَمَّا يُشْرِكُونَ','ٱلَّذِينَ','["ءَامَنَّا","ٱلَّذِينَ","ءَايَٰتٍۭ","ءَايَٰتٍۢ"]'::jsonb,'ٱلَّذِينَ','hard',60,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3218.mp3',3218,NULL,TRUE),
('29-23',29,'العنكبوت',23,'وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ وَلِقَآئِهِۦٓ أُو۟لَٰٓئِكَ يَئِسُوا۟ مِن رَّحْمَتِى وَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌۭ','يَئِسُوا۟','["ءَامَنَّا","يَئِسُوا۟","ءَايَٰتٍۭ","ءَايَٰتٍۢ"]'::jsonb,'يَئِسُوا۟','hard',60,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3363.mp3',3363,NULL,TRUE),
('30-55',30,'الروم',55,'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يُقْسِمُ ٱلْمُجْرِمُونَ مَا لَبِثُوا۟ غَيْرَ سَاعَةٍۢ ۚ كَذَٰلِكَ كَانُوا۟ يُؤْفَكُونَ','لَبِثُوا۟','["ءَايَٰتٍۭ","ءَايَٰتٍۢ","لَبِثُوا۟","ءَامَنَّا"]'::jsonb,'لَبِثُوا۟','hard',60,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3464.mp3',3464,NULL,TRUE),
('34-36',34,'سبأ',36,'قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ','يَشَآءُ','["يَشَآءُ","ءَايَٰتُ","ءَايَةًۭ","ءَاتِنَا"]'::jsonb,'يَشَآءُ','hard',60,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3642.mp3',3642,NULL,TRUE),
('36-69',36,'يس',69,'وَمَا عَلَّمْنَٰهُ ٱلشِّعْرَ وَمَا يَنۢبَغِى لَهُۥٓ ۚ إِنْ هُوَ إِلَّا ذِكْرٌۭ وَقُرْءَانٌۭ مُّبِينٌۭ','إِنْ','["أَنِ","أَنْ","إِنْ","أَمْ"]'::jsonb,'إِنْ','hard',60,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3774.mp3',3774,NULL,TRUE)
