('39-37',39,'الزمر',37,'وَمَن يَهْدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّ ۗ أَلَيْسَ ٱللَّهُ بِعَزِيزٍۢ ذِى ٱنتِقَامٍۢ','مُّضِلٍّ','["ءَاوَىٰٓ","ءَايَةًۭ","مُّضِلٍّ","ءَاتِنَا"]'::jsonb,'مُّضِلٍّ','very_hard',61,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4095.mp3',4095,NULL,TRUE),
('40-49',40,'غافر',49,'وَقَالَ ٱلَّذِينَ فِى ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدْعُوا۟ رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْمًۭا مِّنَ ٱلْعَذَابِ','ٱدْعُوا۟','["ءَاتِنَا","ءَايَةًۭ","ٱدْعُوا۟","ءَاوَىٰٓ"]'::jsonb,'ٱدْعُوا۟','very_hard',61,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4182.mp3',4182,NULL,TRUE),
('41-48',41,'فصلت',48,'وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَدْعُونَ مِن قَبْلُ ۖ وَظَنُّوا۟ مَا لَهُم مِّن مَّحِيصٍۢ','قَبْلُ','["أَتَىٰ","أَجْرٍ","أَبَآ","قَبْلُ"]'::jsonb,'قَبْلُ','very_hard',61,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4266.mp3',4266,NULL,TRUE),
('43-45',43,'الزخرف',45,'وَسْـَٔلْ مَنْ أَرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَآ أَجَعَلْنَا مِن دُونِ ٱلرَّحْمَٰنِ ءَالِهَةًۭ يُعْبَدُونَ','رُّسُلِنَآ','["رُّسُلِنَآ","ءَايَٰتُنَا","ءَاتَىٰهُمُ","ءَامَنُوٓا۟"]'::jsonb,'رُّسُلِنَآ','very_hard',61,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4370.mp3',4370,NULL,TRUE),
('45-18',45,'الجاثية',18,'ثُمَّ جَعَلْنَٰكَ عَلَىٰ شَرِيعَةٍۢ مِّنَ ٱلْأَمْرِ فَٱتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ لَا يَعْلَمُونَ','فَٱتَّبِعْهَا','["أَبْصَٰرِهِمْ","فَٱتَّبِعْهَا","ءَابَآئِهِمْ","ءَابَآءَكُمْ"]'::jsonb,'فَٱتَّبِعْهَا','very_hard',61,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4491.mp3',4491,NULL,TRUE),
('48-23',48,'الفتح',23,'سُنَّةَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ مِن قَبْلُ ۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًۭا','قَبْلُ','["أَتَىٰ","أَجْرٍ","أَبَآ","قَبْلُ"]'::jsonb,'قَبْلُ','very_hard',61,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4606.mp3',4606,NULL,TRUE),
('57-2',57,'الحديد',2,'لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ يُحْىِۦ وَيُمِيتُ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ','وَيُمِيتُ','["ءَايَٰتٍۢ","وَيُمِيتُ","ءَامِنًۭا","ءَايَٰتٌۭ"]'::jsonb,'وَيُمِيتُ','very_hard',61,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5077.mp3',5077,NULL,TRUE),
('60-2',60,'الممتحنة',2,'إِن يَثْقَفُوكُمْ يَكُونُوا۟ لَكُمْ أَعْدَآءًۭ وَيَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ وَأَلْسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّوا۟ لَوْ تَكْفُرُونَ','إِلَيْكُمْ','["ءَامَنُوا۟","ءَاتَيْنَا","إِلَيْكُمْ","ءَالِهَةًۭ"]'::jsonb,'إِلَيْكُمْ','very_hard',61,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5152.mp3',5152,NULL,TRUE),
('67-1',67,'الملك',1,'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ تَبَٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ','بِيَدِهِ','["ءَاتِنَا","ءَايَةًۭ","ءَاوَىٰٓ","بِيَدِهِ"]'::jsonb,'بِيَدِهِ','very_hard',61,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5242.mp3',5242,NULL,TRUE),
('71-21',71,'نوح',21,'قَالَ نُوحٌۭ رَّبِّ إِنَّهُمْ عَصَوْنِى وَٱتَّبَعُوا۟ مَن لَّمْ يَزِدْهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارًۭا','مَن','["إِن","بَل","أَن","مَن"]'::jsonb,'مَن','very_hard',61,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5440.mp3',5440,NULL,TRUE),
('2-24',2,'البقرة',24,'فَإِن لَّمْ تَفْعَلُوا۟ وَلَن تَفْعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ ۖ أُعِدَّتْ لِلْكَٰفِرِينَ','ٱلنَّارَ','["ٱلنَّارَ","ءَاتِنَا","ءَاوَىٰٓ","ءَايَةًۭ"]'::jsonb,'ٱلنَّارَ','very_hard',62,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/31.mp3',31,NULL,TRUE),
('2-115',2,'البقرة',115,'وَلِلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ ۚ فَأَيْنَمَا تُوَلُّوا۟ فَثَمَّ وَجْهُ ٱللَّهِ ۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٌۭ','وَجْهُ','["وَجْهُ","أَجْرٍ","أَبَآ","أَتَىٰ"]'::jsonb,'وَجْهُ','very_hard',62,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/122.mp3',122,NULL,TRUE),
('2-190',2,'البقرة',190,'وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمْ وَلَا تَعْتَدُوٓا۟ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ','وَلَا','["أَئِن","أَلَا","وَلَا","أَنتَ"]'::jsonb,'وَلَا','very_hard',62,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/197.mp3',197,NULL,TRUE),
('3-67',3,'آل عمران',67,'مَا كَانَ إِبْرَٰهِيمُ يَهُودِيًّۭا وَلَا نَصْرَانِيًّۭا وَلَٰكِن كَانَ حَنِيفًۭا مُّسْلِمًۭا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ','كَانَ','["أَئِن","أَنتَ","كَانَ","أَلَا"]'::jsonb,'كَانَ','very_hard',62,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/360.mp3',360,NULL,TRUE),
('3-134',3,'آل عمران',134,'ٱلَّذِينَ يُنفِقُونَ فِى ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلْكَٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ','ٱلْغَيْظَ','["ءَامِنًۭا","ءَايَٰتٍۢ","ءَايَٰتٌۭ","ٱلْغَيْظَ"]'::jsonb,'ٱلْغَيْظَ','very_hard',62,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/427.mp3',427,NULL,TRUE),
('4-42',4,'النساء',42,'يَوْمَئِذٍۢ يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ وَعَصَوُا۟ ٱلرَّسُولَ لَوْ تُسَوَّىٰ بِهِمُ ٱلْأَرْضُ وَلَا يَكْتُمُونَ ٱللَّهَ حَدِيثًۭا','تُسَوَّىٰ','["ءَايَٰتٌۭ","ءَايَٰتٍۢ","تُسَوَّىٰ","ءَامِنًۭا"]'::jsonb,'تُسَوَّىٰ','very_hard',62,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/535.mp3',535,NULL,TRUE),
('5-21',5,'المائدة',21,'يَٰقَوْمِ ٱدْخُلُوا۟ ٱلْأَرْضَ ٱلْمُقَدَّسَةَ ٱلَّتِى كَتَبَ ٱللَّهُ لَكُمْ وَلَا تَرْتَدُّوا۟ عَلَىٰٓ أَدْبَارِكُمْ فَتَنقَلِبُوا۟ خَٰسِرِينَ','لَكُمْ','["لَكُمْ","أَجْرٍ","أَتَىٰ","أَبَآ"]'::jsonb,'لَكُمْ','very_hard',62,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/690.mp3',690,NULL,TRUE),
('5-63',5,'المائدة',63,'لَوْلَا يَنْهَىٰهُمُ ٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ عَن قَوْلِهِمُ ٱلْإِثْمَ وَأَكْلِهِمُ ٱلسُّحْتَ ۚ لَبِئْسَ مَا كَانُوا۟ يَصْنَعُونَ','ٱلْإِثْمَ','["ءَايَٰتٌۭ","ءَايَٰتٍۢ","ءَامِنًۭا","ٱلْإِثْمَ"]'::jsonb,'ٱلْإِثْمَ','very_hard',62,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/732.mp3',732,NULL,TRUE),
('6-98',6,'الأنعام',98,'وَهُوَ ٱلَّذِىٓ أَنشَأَكُم مِّن نَّفْسٍۢ وَٰحِدَةٍۢ فَمُسْتَقَرٌّۭ وَمُسْتَوْدَعٌۭ ۗ قَدْ فَصَّلْنَا ٱلْءَايَٰتِ لِقَوْمٍۢ يَفْقَهُونَ','فَمُسْتَقَرٌّۭ','["أَهَٰٓؤُلَآءِ","فَمُسْتَقَرٌّۭ","أَمَانِيُّهُمْ","أَبْلَغْتُكُمْ"]'::jsonb,'فَمُسْتَقَرٌّۭ','very_hard',62,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/887.mp3',887,NULL,TRUE),
('7-72',7,'الأعراف',72,'فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحْمَةٍۢ مِّنَّا وَقَطَعْنَا دَابِرَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا ۖ وَمَا كَانُوا۟ مُؤْمِنِينَ','دَابِرَ','["ءَاسَىٰ","دَابِرَ","ءَادَمَ","ءَامَنَ"]'::jsonb,'دَابِرَ','very_hard',62,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1026.mp3',1026,NULL,TRUE),
('7-153',7,'الأعراف',153,'وَٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُوا۟ مِنۢ بَعْدِهَا وَءَامَنُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌۭ رَّحِيمٌۭ','وَءَامَنُوٓا۟','["ءَابَآءَكُمْ","وَءَامَنُوٓا۟","أَبْصَٰرِهِمْ","ءَابَآئِهِمْ"]'::jsonb,'وَءَامَنُوٓا۟','very_hard',63,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1107.mp3',1107,NULL,TRUE),
('8-71',8,'الأنفال',71,'وَإِن يُرِيدُوا۟ خِيَانَتَكَ فَقَدْ خَانُوا۟ ٱللَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','مِن','["مِن","أَن","بَل","إِن"]'::jsonb,'مِن','very_hard',63,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1231.mp3',1231,NULL,TRUE),
('9-89',9,'التوبة',89,'أَعَدَّ ٱللَّهُ لَهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ','تَحْتِهَا','["تَحْتِهَا","ءَايَٰتٍۢ","ءَايَٰتٌۭ","ءَامِنًۭا"]'::jsonb,'تَحْتِهَا','very_hard',63,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1324.mp3',1324,NULL,TRUE),
('11-10',11,'هود',10,'وَلَئِنْ أَذَقْنَٰهُ نَعْمَآءَ بَعْدَ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّىٓ ۚ إِنَّهُۥ لَفَرِحٌۭ فَخُورٌ','لَيَقُولَنَّ','["ءَابَآءَنَا","لَيَقُولَنَّ","ءَاتَىٰهُمَا","ءَاتَيْنَٰهُ"]'::jsonb,'لَيَقُولَنَّ','very_hard',63,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1483.mp3',1483,NULL,TRUE),
('12-28',12,'يوسف',28,'فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٍۢ قَالَ إِنَّهُۥ مِن كَيْدِكُنَّ ۖ إِنَّ كَيْدَكُنَّ عَظِيمٌۭ','قَالَ','["أَئِن","قَالَ","أَنتَ","أَلَا"]'::jsonb,'قَالَ','very_hard',63,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1624.mp3',1624,NULL,TRUE),
('13-32',13,'الرعد',32,'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍۢ مِّن قَبْلِكَ فَأَمْلَيْتُ لِلَّذِينَ كَفَرُوا۟ ثُمَّ أَخَذْتُهُمْ ۖ فَكَيْفَ كَانَ عِقَابِ','لِلَّذِينَ','["ءَالِهَةًۭ","ءَاتَيْنَا","ءَامَنُوا۟","لِلَّذِينَ"]'::jsonb,'لِلَّذِينَ','very_hard',63,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1739.mp3',1739,NULL,TRUE),
('16-10',16,'النحل',10,'هُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ ۖ لَّكُم مِّنْهُ شَرَابٌۭ وَمِنْهُ شَجَرٌۭ فِيهِ تُسِيمُونَ','لَّكُم','["لَّكُم","أَبَآ","أَتَىٰ","أَجْرٍ"]'::jsonb,'لَّكُم','very_hard',63,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1911.mp3',1911,NULL,TRUE),
('17-13',17,'الإسراء',13,'وَكُلَّ إِنسَٰنٍ أَلْزَمْنَٰهُ طَٰٓئِرَهُۥ فِى عُنُقِهِۦ ۖ وَنُخْرِجُ لَهُۥ يَوْمَ ٱلْقِيَٰمَةِ كِتَٰبًۭا يَلْقَىٰهُ مَنشُورًا','وَنُخْرِجُ','["ءَامَنُوا۟","وَنُخْرِجُ","ءَاتَيْنَا","ءَالِهَةًۭ"]'::jsonb,'وَنُخْرِجُ','very_hard',63,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2042.mp3',2042,NULL,TRUE),
('17-80',17,'الإسراء',80,'وَقُل رَّبِّ أَدْخِلْنِى مُدْخَلَ صِدْقٍۢ وَأَخْرِجْنِى مُخْرَجَ صِدْقٍۢ وَٱجْعَل لِّى مِن لَّدُنكَ سُلْطَٰنًۭا نَّصِيرًۭا','صِدْقٍۢ','["ءَامَنَ","ءَاسَىٰ","ءَادَمَ","صِدْقٍۢ"]'::jsonb,'صِدْقٍۢ','very_hard',63,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2109.mp3',2109,NULL,TRUE),
