('29-28',29,'العنكبوت',28,'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ إِنَّكُمْ لَتَأْتُونَ ٱلْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍۢ مِّنَ ٱلْعَٰلَمِينَ','مَا','["بَل","مَا","إِن","أَن"]'::jsonb,'مَا','very_hard',64,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3368.mp3',3368,NULL,TRUE),
('32-22',32,'السجدة',22,'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ أَعْرَضَ عَنْهَآ ۚ إِنَّا مِنَ ٱلْمُجْرِمِينَ مُنتَقِمُونَ','ثُمَّ','["أَنتَ","أَئِن","ثُمَّ","أَلَا"]'::jsonb,'ثُمَّ','very_hard',64,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3525.mp3',3525,NULL,TRUE),
