('40-44',40,'غافر',44,'فَسَتَذْكُرُونَ مَآ أَقُولُ لَكُمْ ۚ وَأُفَوِّضُ أَمْرِىٓ إِلَى ٱللَّهِ ۚ إِنَّ ٱللَّهَ بَصِيرٌۢ بِٱلْعِبَادِ','إِلَى','["أَنتَ","أَئِن","إِلَى","أَلَا"]'::jsonb,'إِلَى','very_hard',65,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4177.mp3',4177,NULL,TRUE),
('42-28',42,'الشورى',28,'وَهُوَ ٱلَّذِى يُنَزِّلُ ٱلْغَيْثَ مِنۢ بَعْدِ مَا قَنَطُوا۟ وَيَنشُرُ رَحْمَتَهُۥ ۚ وَهُوَ ٱلْوَلِىُّ ٱلْحَمِيدُ','مَا','["إِن","أَن","بَل","مَا"]'::jsonb,'مَا','very_hard',65,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4300.mp3',4300,NULL,TRUE),
('45-30',45,'الجاثية',30,'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُدْخِلُهُمْ رَبُّهُمْ فِى رَحْمَتِهِۦ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْمُبِينُ','رَبُّهُمْ','["ءَايَٰتٍۢ","ءَايَٰتٌۭ","ءَامِنًۭا","رَبُّهُمْ"]'::jsonb,'رَبُّهُمْ','very_hard',65,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4503.mp3',4503,NULL,TRUE),
('47-36',47,'محمد',36,'إِنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌۭ وَلَهْوٌۭ ۚ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ يُؤْتِكُمْ أُجُورَكُمْ وَلَا يَسْـَٔلْكُمْ أَمْوَٰلَكُمْ','تُؤْمِنُوا۟','["ءَاتَىٰهُمُ","ءَامَنُوٓا۟","ءَايَٰتُنَا","تُؤْمِنُوا۟"]'::jsonb,'تُؤْمِنُوا۟','very_hard',65,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4581.mp3',4581,NULL,TRUE),
('67-8',67,'الملك',8,'تَكَادُ تَمَيَّزُ مِنَ ٱلْغَيْظِ ۖ كُلَّمَآ أُلْقِىَ فِيهَا فَوْجٌۭ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌۭ','فِيهَا','["أَتَىٰ","أَبَآ","فِيهَا","أَجْرٍ"]'::jsonb,'فِيهَا','very_hard',65,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5249.mp3',5249,NULL,TRUE),
('2-31',2,'البقرة',31,'وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمْ صَٰدِقِينَ','ٱلْمَلَٰٓئِكَةِ','["أَغْرَقْنَٰهُمْ","بِأَفْوَٰهِهِمْ","ٱلْمَلَٰٓئِكَةِ","بِأَمْوَٰلِهِمْ"]'::jsonb,'ٱلْمَلَٰٓئِكَةِ','very_hard',65,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/38.mp3',38,NULL,TRUE),
('2-205',2,'البقرة',205,'وَإِذَا تَوَلَّىٰ سَعَىٰ فِى ٱلْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ ٱلْحَرْثَ وَٱلنَّسْلَ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلْفَسَادَ','وَيُهْلِكَ','["ءَامَنُوا۟","ءَاتَيْنَا","ءَالِهَةًۭ","وَيُهْلِكَ"]'::jsonb,'وَيُهْلِكَ','very_hard',65,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/212.mp3',212,NULL,TRUE),
('3-31',3,'آل عمران',31,'قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ','ٱللَّهُ','["ٱللَّهُ","ءَاسَىٰ","ءَامَنَ","ءَادَمَ"]'::jsonb,'ٱللَّهُ','very_hard',66,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/324.mp3',324,NULL,TRUE),
