('4-139',4,'النساء',139,'ٱلَّذِينَ يَتَّخِذُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۚ أَيَبْتَغُونَ عِندَهُمُ ٱلْعِزَّةَ فَإِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًۭا','أَيَبْتَغُونَ','["ءَابَآءَكُمْ","ءَابَآئِهِمْ","أَيَبْتَغُونَ","أَبْصَٰرِهِمْ"]'::jsonb,'أَيَبْتَغُونَ','very_hard',66,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/632.mp3',632,NULL,TRUE),
('5-81',5,'المائدة',81,'وَلَوْ كَانُوا۟ يُؤْمِنُونَ بِٱللَّهِ وَٱلنَّبِىِّ وَمَآ أُنزِلَ إِلَيْهِ مَا ٱتَّخَذُوهُمْ أَوْلِيَآءَ وَلَٰكِنَّ كَثِيرًۭا مِّنْهُمْ فَٰسِقُونَ','إِلَيْهِ','["إِلَيْهِ","ءَاتِنَا","ءَاوَىٰٓ","ءَايَةًۭ"]'::jsonb,'إِلَيْهِ','very_hard',66,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/750.mp3',750,NULL,TRUE),
('6-33',6,'الأنعام',33,'قَدْ نَعْلَمُ إِنَّهُۥ لَيَحْزُنُكَ ٱلَّذِى يَقُولُونَ ۖ فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ','لَا','["لَا","إِن","بَل","أَن"]'::jsonb,'لَا','very_hard',66,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/822.mp3',822,NULL,TRUE),
('7-64',7,'الأعراف',64,'فَكَذَّبُوهُ فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِى ٱلْفُلْكِ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًا عَمِينَ','ٱلَّذِينَ','["ءَايَٰتٌۭ","ءَايَٰتٍۢ","ءَامِنًۭا","ٱلَّذِينَ"]'::jsonb,'ٱلَّذِينَ','very_hard',66,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1018.mp3',1018,NULL,TRUE),
('9-32',9,'التوبة',32,'يُرِيدُونَ أَن يُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَيَأْبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ','ٱللَّهُ','["ءَاسَىٰ","ٱللَّهُ","ءَامَنَ","ءَادَمَ"]'::jsonb,'ٱللَّهُ','very_hard',66,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1267.mp3',1267,NULL,TRUE),
('10-10',10,'يونس',10,'دَعْوَىٰهُمْ فِيهَا سُبْحَٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَٰمٌۭ ۚ وَءَاخِرُ دَعْوَىٰهُمْ أَنِ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ','وَءَاخِرُ','["وَءَاخِرُ","ءَايَٰتٍۢ","ءَايَٰتٌۭ","ءَامِنًۭا"]'::jsonb,'وَءَاخِرُ','very_hard',66,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1374.mp3',1374,NULL,TRUE),
('11-1',11,'هود',1,'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر ۚ كِتَٰبٌ أُحْكِمَتْ ءَايَٰتُهُۥ ثُمَّ فُصِّلَتْ مِن لَّدُنْ حَكِيمٍ خَبِيرٍ','ءَايَٰتُهُۥ','["ءَامَنُوٓا۟","ءَايَٰتُنَا","ءَايَٰتُهُۥ","ءَاتَىٰهُمُ"]'::jsonb,'ءَايَٰتُهُۥ','very_hard',66,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1474.mp3',1474,NULL,TRUE),
('12-4',12,'يوسف',4,'إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّى رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًۭا وَٱلشَّمْسَ وَٱلْقَمَرَ رَأَيْتُهُمْ لِى سَٰجِدِينَ','أَحَدَ','["أَجْرٍ","أَتَىٰ","أَبَآ","أَحَدَ"]'::jsonb,'أَحَدَ','very_hard',66,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1600.mp3',1600,NULL,TRUE),
('14-19',14,'إبراهيم',19,'أَلَمْ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۚ إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍۢ جَدِيدٍۢ','بِٱلْحَقِّ','["ءَالِهَةًۭ","ءَامَنُوا۟","بِٱلْحَقِّ","ءَاتَيْنَا"]'::jsonb,'بِٱلْحَقِّ','very_hard',67,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1769.mp3',1769,NULL,TRUE),
('16-64',16,'النحل',64,'وَمَآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِى ٱخْتَلَفُوا۟ فِيهِ ۙ وَهُدًۭى وَرَحْمَةًۭ لِّقَوْمٍۢ يُؤْمِنُونَ','ٱلَّذِى','["ءَادَمَ","ٱلَّذِى","ءَاسَىٰ","ءَامَنَ"]'::jsonb,'ٱلَّذِى','very_hard',67,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1965.mp3',1965,NULL,TRUE),
