('12-63',12,'يوسف',63,'فَلَمَّا رَجَعُوٓا۟ إِلَىٰٓ أَبِيهِمْ قَالُوا۟ يَٰٓأَبَانَا مُنِعَ مِنَّا ٱلْكَيْلُ فَأَرْسِلْ مَعَنَآ أَخَانَا نَكْتَلْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ','ٱلْكَيْلُ','["ٱلْكَيْلُ","ءَايَٰتٍۢ","ءَايَٰتٌۭ","ءَامِنًۭا"]'::jsonb,'ٱلْكَيْلُ','very_hard',70,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1659.mp3',1659,NULL,TRUE),
('15-85',15,'الحجر',85,'وَمَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ ۗ وَإِنَّ ٱلسَّاعَةَ لَءَاتِيَةٌۭ ۖ فَٱصْفَحِ ٱلصَّفْحَ ٱلْجَمِيلَ','بِٱلْحَقِّ','["بِٱلْحَقِّ","ءَاتَيْنَا","ءَالِهَةًۭ","ءَامَنُوا۟"]'::jsonb,'بِٱلْحَقِّ','very_hard',70,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1887.mp3',1887,NULL,TRUE),
('16-111',16,'النحل',111,'۞ يَوْمَ تَأْتِى كُلُّ نَفْسٍۢ تُجَٰدِلُ عَن نَّفْسِهَا وَتُوَفَّىٰ كُلُّ نَفْسٍۢ مَّا عَمِلَتْ وَهُمْ لَا يُظْلَمُونَ','وَتُوَفَّىٰ','["ءَاتَىٰهُمُ","ءَايَٰتُنَا","وَتُوَفَّىٰ","ءَامَنُوٓا۟"]'::jsonb,'وَتُوَفَّىٰ','very_hard',70,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2012.mp3',2012,NULL,TRUE),
('18-10',18,'الكهف',10,'إِذْ أَوَى ٱلْفِتْيَةُ إِلَى ٱلْكَهْفِ فَقَالُوا۟ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحْمَةًۭ وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًۭا','مِن','["مِن","إِن","بَل","أَن"]'::jsonb,'مِن','very_hard',70,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2150.mp3',2150,NULL,TRUE),
('20-61',20,'طه',61,'قَالَ لَهُم مُّوسَىٰ وَيْلَكُمْ لَا تَفْتَرُوا۟ عَلَى ٱللَّهِ كَذِبًۭا فَيُسْحِتَكُم بِعَذَابٍۢ ۖ وَقَدْ خَابَ مَنِ ٱفْتَرَىٰ','ٱللَّهِ','["ٱللَّهِ","ءَاسَىٰ","ءَادَمَ","ءَامَنَ"]'::jsonb,'ٱللَّهِ','very_hard',70,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2409.mp3',2409,NULL,TRUE),
('22-63',22,'الحج',63,'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَتُصْبِحُ ٱلْأَرْضُ مُخْضَرَّةً ۗ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٌۭ','مَآءًۭ','["ءَامَنَ","ءَاسَىٰ","ءَادَمَ","مَآءًۭ"]'::jsonb,'مَآءًۭ','very_hard',70,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2658.mp3',2658,NULL,TRUE)
