('25-45',25,'الفرقان',45,'أَلَمْ تَرَ إِلَىٰ رَبِّكَ كَيْفَ مَدَّ ٱلظِّلَّ وَلَوْ شَآءَ لَجَعَلَهُۥ سَاكِنًۭا ثُمَّ جَعَلْنَا ٱلشَّمْسَ عَلَيْهِ دَلِيلًۭا','شَآءَ','["أَبَآ","شَآءَ","أَحَدٍ","أَتَىٰ"]'::jsonb,'شَآءَ','very_hard',71,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2900.mp3',2900,NULL,TRUE),
('27-66',27,'النمل',66,'بَلِ ٱدَّٰرَكَ عِلْمُهُمْ فِى ٱلْءَاخِرَةِ ۚ بَلْ هُمْ فِى شَكٍّۢ مِّنْهَا ۖ بَلْ هُم مِّنْهَا عَمُونَ','فِى','["فِى","بَل","إِن","أَن"]'::jsonb,'فِى','very_hard',71,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3225.mp3',3225,NULL,TRUE),
('28-86',28,'القصص',86,'وَمَا كُنتَ تَرْجُوٓا۟ أَن يُلْقَىٰٓ إِلَيْكَ ٱلْكِتَٰبُ إِلَّا رَحْمَةًۭ مِّن رَّبِّكَ ۖ فَلَا تَكُونَنَّ ظَهِيرًۭا لِّلْكَٰفِرِينَ','إِلَّا','["إِلَّا","أَبَآ","أَحَدٍ","أَتَىٰ"]'::jsonb,'إِلَّا','very_hard',71,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3338.mp3',3338,NULL,TRUE),
('29-67',29,'العنكبوت',67,'أَوَلَمْ يَرَوْا۟ أَنَّا جَعَلْنَا حَرَمًا ءَامِنًۭا وَيُتَخَطَّفُ ٱلنَّاسُ مِنْ حَوْلِهِمْ ۚ أَفَبِٱلْبَٰطِلِ يُؤْمِنُونَ وَبِنِعْمَةِ ٱللَّهِ يَكْفُرُونَ','ٱلنَّاسُ','["ٱلنَّاسُ","ءَايَةًۭ","ءَاتِنَا","ءَاوَىٰٓ"]'::jsonb,'ٱلنَّاسُ','very_hard',71,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3407.mp3',3407,NULL,TRUE),
('32-13',32,'السجدة',13,'وَلَوْ شِئْنَا لَءَاتَيْنَا كُلَّ نَفْسٍ هُدَىٰهَا وَلَٰكِنْ حَقَّ ٱلْقَوْلُ مِنِّى لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ','ٱلْقَوْلُ','["ٱلْقَوْلُ","ءَايَٰتٌۭ","ءَالَآءَ","ءَامِنًۭا"]'::jsonb,'ٱلْقَوْلُ','very_hard',71,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3516.mp3',3516,NULL,TRUE),
('34-6',34,'سبأ',6,'وَيَرَى ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ ٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ هُوَ ٱلْحَقَّ وَيَهْدِىٓ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ','رَّبِّكَ','["ءَايَةًۭ","ءَاوَىٰٓ","رَّبِّكَ","ءَاتِنَا"]'::jsonb,'رَّبِّكَ','very_hard',71,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3612.mp3',3612,NULL,TRUE),
('35-29',35,'فاطر',29,'إِنَّ ٱلَّذِينَ يَتْلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّۭا وَعَلَانِيَةًۭ يَرْجُونَ تِجَٰرَةًۭ لَّن تَبُورَ','مِمَّا','["مِمَّا","أَتَىٰ","أَحَدٍ","أَبَآ"]'::jsonb,'مِمَّا','very_hard',71,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3689.mp3',3689,NULL,TRUE),
('40-3',40,'غافر',3,'غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوْبِ شَدِيدِ ٱلْعِقَابِ ذِى ٱلطَّوْلِ ۖ لَآ إِلَٰهَ إِلَّا هُوَ ۖ إِلَيْهِ ٱلْمَصِيرُ','ٱلطَّوْلِ','["ءَالَآءَ","ءَايَٰتٌۭ","ءَامِنًۭا","ٱلطَّوْلِ"]'::jsonb,'ٱلطَّوْلِ','very_hard',71,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4136.mp3',4136,NULL,TRUE),
('41-29',41,'فصلت',29,'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ رَبَّنَآ أَرِنَا ٱلَّذَيْنِ أَضَلَّانَا مِنَ ٱلْجِنِّ وَٱلْإِنسِ نَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا لِيَكُونَا مِنَ ٱلْأَسْفَلِينَ','ٱلْجِنِّ','["ٱلْجِنِّ","ءَاوَىٰٓ","ءَايَةًۭ","ءَاتِنَا"]'::jsonb,'ٱلْجِنِّ','very_hard',71,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4247.mp3',4247,NULL,TRUE),
('43-24',43,'الزخرف',24,'۞ قَٰلَ أَوَلَوْ جِئْتُكُم بِأَهْدَىٰ مِمَّا وَجَدتُّمْ عَلَيْهِ ءَابَآءَكُمْ ۖ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ','ءَابَآءَكُمْ','["ءَابَآءَنَآ","ءَابَآءَكُمْ","ءَابَآئِهِمْ","ءَابَآؤُهُمْ"]'::jsonb,'ءَابَآءَكُمْ','very_hard',71,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4349.mp3',4349,NULL,TRUE),
('53-31',53,'النجم',31,'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لِيَجْزِىَ ٱلَّذِينَ أَسَٰٓـُٔوا۟ بِمَا عَمِلُوا۟ وَيَجْزِىَ ٱلَّذِينَ أَحْسَنُوا۟ بِٱلْحُسْنَى','ٱلَّذِينَ','["ءَايَٰتٌۭ","ٱلَّذِينَ","ءَالَآءَ","ءَامِنًۭا"]'::jsonb,'ٱلَّذِينَ','very_hard',72,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4815.mp3',4815,NULL,TRUE),
('61-1',61,'الصف',1,'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ','فِى','["أَن","بَل","فِى","إِن"]'::jsonb,'فِى','very_hard',72,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5164.mp3',5164,NULL,TRUE),
('2-70',2,'البقرة',70,'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ إِنَّ ٱلْبَقَرَ تَشَٰبَهَ عَلَيْنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهْتَدُونَ','إِنَّ','["أَنتَ","إِنَّ","أَنَّ","أَلَا"]'::jsonb,'إِنَّ','very_hard',72,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/77.mp3',77,NULL,TRUE),
('2-135',2,'البقرة',135,'وَقَالُوا۟ كُونُوا۟ هُودًا أَوْ نَصَٰرَىٰ تَهْتَدُوا۟ ۗ قُلْ بَلْ مِلَّةَ إِبْرَٰهِۦمَ حَنِيفًۭا ۖ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ','بَلْ','["أَمِ","أَمْ","بَلْ","أَنِ"]'::jsonb,'بَلْ','very_hard',72,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/142.mp3',142,NULL,TRUE),
('2-188',2,'البقرة',188,'وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ وَتُدْلُوا۟ بِهَآ إِلَى ٱلْحُكَّامِ لِتَأْكُلُوا۟ فَرِيقًۭا مِّنْ أَمْوَٰلِ ٱلنَّاسِ بِٱلْإِثْمِ وَأَنتُمْ تَعْلَمُونَ','ٱلْحُكَّامِ','["ءَايَٰتُنَا","ٱلْحُكَّامِ","ءَاتَىٰهُمُ","ءَامَنُوٓا۟"]'::jsonb,'ٱلْحُكَّامِ','very_hard',72,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/195.mp3',195,NULL,TRUE),
('3-38',3,'آل عمران',38,'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥ ۖ قَالَ رَبِّ هَبْ لِى مِن لَّدُنكَ ذُرِّيَّةًۭ طَيِّبَةً ۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ','لِى','["لِى","أَن","بَل","إِن"]'::jsonb,'لِى','very_hard',72,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/331.mp3',331,NULL,TRUE),
('4-143',4,'النساء',143,'مُّذَبْذَبِينَ بَيْنَ ذَٰلِكَ لَآ إِلَىٰ هَٰٓؤُلَآءِ وَلَآ إِلَىٰ هَٰٓؤُلَآءِ ۚ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًۭا','هَٰٓؤُلَآءِ','["ءَابَآؤُهُم","ءَايَٰتِهِۦٓ","ءَابَآءَنَا","هَٰٓؤُلَآءِ"]'::jsonb,'هَٰٓؤُلَآءِ','very_hard',72,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/636.mp3',636,NULL,TRUE),
('5-53',5,'المائدة',53,'وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓا۟ أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ ۙ إِنَّهُمْ لَمَعَكُمْ ۚ حَبِطَتْ أَعْمَٰلُهُمْ فَأَصْبَحُوا۟ خَٰسِرِينَ','جَهْدَ','["جَهْدَ","أَتَىٰ","أَحَدٍ","أَبَآ"]'::jsonb,'جَهْدَ','very_hard',72,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/722.mp3',722,NULL,TRUE),
('6-88',6,'الأنعام',88,'ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۚ وَلَوْ أَشْرَكُوا۟ لَحَبِطَ عَنْهُم مَّا كَانُوا۟ يَعْمَلُونَ','عِبَادِهِۦ','["ءَاتَيْنَا","ءَالِهَةًۭ","عِبَادِهِۦ","ءَامَنُوا۟"]'::jsonb,'عِبَادِهِۦ','very_hard',72,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/877.mp3',877,NULL,TRUE),
('7-30',7,'الأعراف',30,'فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيْهِمُ ٱلضَّلَٰلَةُ ۗ إِنَّهُمُ ٱتَّخَذُوا۟ ٱلشَّيَٰطِينَ أَوْلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ','ٱلشَّيَٰطِينَ','["ءَابَآءَنَآ","ءَابَآؤُهُمْ","ءَابَآءَكُمْ","ٱلشَّيَٰطِينَ"]'::jsonb,'ٱلشَّيَٰطِينَ','very_hard',72,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/984.mp3',984,NULL,TRUE),
('8-39',8,'الأنفال',39,'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌۭ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِ ۚ فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ بَصِيرٌۭ','لِلَّهِ','["ءَاسَىٰ","ءَاخَرَ","ءَادَمَ","لِلَّهِ"]'::jsonb,'لِلَّهِ','very_hard',73,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1199.mp3',1199,NULL,TRUE),
('9-63',9,'التوبة',63,'أَلَمْ يَعْلَمُوٓا۟ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدًۭا فِيهَا ۚ ذَٰلِكَ ٱلْخِزْىُ ٱلْعَظِيمُ','لَهُۥ','["أَنتَ","أَنَّ","لَهُۥ","أَلَا"]'::jsonb,'لَهُۥ','very_hard',73,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1298.mp3',1298,NULL,TRUE),
('9-123',9,'التوبة',123,'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قَٰتِلُوا۟ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلْكُفَّارِ وَلْيَجِدُوا۟ فِيكُمْ غِلْظَةًۭ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ','وَلْيَجِدُوا۟','["ءَابَآءَنَآ","ءَابَآؤُهُمْ","ءَابَآءَكُمْ","وَلْيَجِدُوا۟"]'::jsonb,'وَلْيَجِدُوا۟','very_hard',73,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1358.mp3',1358,NULL,TRUE),
('10-87',10,'يونس',87,'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوْمِكُمَا بِمِصْرَ بُيُوتًۭا وَٱجْعَلُوا۟ بُيُوتَكُمْ قِبْلَةًۭ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ','بُيُوتًۭا','["ءَامِنًۭا","ءَالَآءَ","ءَايَٰتٌۭ","بُيُوتًۭا"]'::jsonb,'بُيُوتًۭا','very_hard',73,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1451.mp3',1451,NULL,TRUE),
('11-64',11,'هود',64,'وَيَٰقَوْمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةًۭ فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍۢ فَيَأْخُذَكُمْ عَذَابٌۭ قَرِيبٌۭ','فِىٓ','["أَمْ","فِىٓ","أَمِ","أَنِ"]'::jsonb,'فِىٓ','very_hard',73,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1537.mp3',1537,NULL,TRUE),
('12-69',12,'يوسف',69,'وَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَخَاهُ ۖ قَالَ إِنِّىٓ أَنَا۠ أَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَعْمَلُونَ','إِنِّىٓ','["ءَادَمَ","إِنِّىٓ","ءَاخَرَ","ءَاسَىٰ"]'::jsonb,'إِنِّىٓ','very_hard',73,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1665.mp3',1665,NULL,TRUE),
('14-13',14,'إبراهيم',13,'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِرُسُلِهِمْ لَنُخْرِجَنَّكُم مِّنْ أَرْضِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا ۖ فَأَوْحَىٰٓ إِلَيْهِمْ رَبُّهُمْ لَنُهْلِكَنَّ ٱلظَّٰلِمِينَ','لَتَعُودُنَّ','["ءَابَآءَنَا","ءَايَٰتِهِۦٓ","ءَابَآؤُهُم","لَتَعُودُنَّ"]'::jsonb,'لَتَعُودُنَّ','very_hard',73,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1763.mp3',1763,NULL,TRUE),
('16-25',16,'النحل',25,'لِيَحْمِلُوٓا۟ أَوْزَارَهُمْ كَامِلَةًۭ يَوْمَ ٱلْقِيَٰمَةِ ۙ وَمِنْ أَوْزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيْرِ عِلْمٍ ۗ أَلَا سَآءَ مَا يَزِرُونَ','ٱلَّذِينَ','["ءَامِنًۭا","ٱلَّذِينَ","ءَالَآءَ","ءَايَٰتٌۭ"]'::jsonb,'ٱلَّذِينَ','very_hard',73,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1926.mp3',1926,NULL,TRUE),
('16-103',16,'النحل',103,'وَلَقَدْ نَعْلَمُ أَنَّهُمْ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٌۭ ۗ لِّسَانُ ٱلَّذِى يُلْحِدُونَ إِلَيْهِ أَعْجَمِىٌّۭ وَهَٰذَا لِسَانٌ عَرَبِىٌّۭ مُّبِينٌ','ٱلَّذِى','["ٱلَّذِى","ءَاخَرَ","ءَادَمَ","ءَاسَىٰ"]'::jsonb,'ٱلَّذِى','very_hard',73,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2004.mp3',2004,NULL,TRUE),
('19-21',19,'مريم',21,'قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَىَّ هَيِّنٌۭ ۖ وَلِنَجْعَلَهُۥٓ ءَايَةًۭ لِّلنَّاسِ وَرَحْمَةًۭ مِّنَّا ۚ وَكَانَ أَمْرًۭا مَّقْضِيًّۭا','وَلِنَجْعَلَهُۥٓ','["بِٱلْمُؤْمِنِينَ","أَوْلِيَآؤُكُمْ","أَفَبِٱلْبَٰطِلِ","وَلِنَجْعَلَهُۥٓ"]'::jsonb,'وَلِنَجْعَلَهُۥٓ','very_hard',73,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2271.mp3',2271,NULL,TRUE),
('21-84',21,'الأنبياء',84,'فَٱسْتَجَبْنَا لَهُۥ فَكَشَفْنَا مَا بِهِۦ مِن ضُرٍّۢ ۖ وَءَاتَيْنَٰهُ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةًۭ مِّنْ عِندِنَا وَذِكْرَىٰ لِلْعَٰبِدِينَ','أَهْلَهُۥ','["أَهْلَهُۥ","ءَامِنًۭا","ءَالَآءَ","ءَايَٰتٌۭ"]'::jsonb,'أَهْلَهُۥ','very_hard',74,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2567.mp3',2567,NULL,TRUE),
('24-30',24,'النور',30,'قُل لِّلْمُؤْمِنِينَ يَغُضُّوا۟ مِنْ أَبْصَٰرِهِمْ وَيَحْفَظُوا۟ فُرُوجَهُمْ ۚ ذَٰلِكَ أَزْكَىٰ لَهُمْ ۗ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا يَصْنَعُونَ','ذَٰلِكَ','["ذَٰلِكَ","ءَاسَىٰ","ءَاخَرَ","ءَادَمَ"]'::jsonb,'ذَٰلِكَ','very_hard',74,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2821.mp3',2821,NULL,TRUE),
('25-44',25,'الفرقان',44,'أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ ۚ إِنْ هُمْ إِلَّا كَٱلْأَنْعَٰمِ ۖ بَلْ هُمْ أَضَلُّ سَبِيلًا','إِنْ','["أَمْ","إِنْ","أَنِ","أَمِ"]'::jsonb,'إِنْ','very_hard',74,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2899.mp3',2899,NULL,TRUE),
('27-92',27,'النمل',92,'وَأَنْ أَتْلُوَا۟ ٱلْقُرْءَانَ ۖ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَقُلْ إِنَّمَآ أَنَا۠ مِنَ ٱلْمُنذِرِينَ','لِنَفْسِهِۦ','["ءَايَٰتُنَا","ءَامَنُوٓا۟","لِنَفْسِهِۦ","ءَاتَىٰهُمُ"]'::jsonb,'لِنَفْسِهِۦ','very_hard',74,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3251.mp3',3251,NULL,TRUE),
('28-60',28,'القصص',60,'وَمَآ أُوتِيتُم مِّن شَىْءٍۢ فَمَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَزِينَتُهَا ۚ وَمَا عِندَ ٱللَّهِ خَيْرٌۭ وَأَبْقَىٰٓ ۚ أَفَلَا تَعْقِلُونَ','وَزِينَتُهَا','["وَزِينَتُهَا","ءَابَآءَنَا","ءَابَآؤُهُم","ءَايَٰتِهِۦٓ"]'::jsonb,'وَزِينَتُهَا','very_hard',74,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3312.mp3',3312,NULL,TRUE),
('29-50',29,'العنكبوت',50,'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَٰتٌۭ مِّن رَّبِّهِۦ ۖ قُلْ إِنَّمَا ٱلْءَايَٰتُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌۭ مُّبِينٌ','إِنَّمَا','["ءَاوَىٰٓ","ءَايَةًۭ","ءَاتِنَا","إِنَّمَا"]'::jsonb,'إِنَّمَا','very_hard',74,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3390.mp3',3390,NULL,TRUE),
('31-14',31,'لقمان',14,'وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ حَمَلَتْهُ أُمُّهُۥ وَهْنًا عَلَىٰ وَهْنٍۢ وَفِصَٰلُهُۥ فِى عَامَيْنِ أَنِ ٱشْكُرْ لِى وَلِوَٰلِدَيْكَ إِلَىَّ ٱلْمَصِيرُ','وَفِصَٰلُهُۥ','["ءَايَٰتِهِۦٓ","ءَابَآؤُهُم","وَفِصَٰلُهُۥ","ءَابَآءَنَا"]'::jsonb,'وَفِصَٰلُهُۥ','very_hard',74,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3483.mp3',3483,NULL,TRUE),
('33-24',33,'الأحزاب',24,'لِّيَجْزِىَ ٱللَّهُ ٱلصَّٰدِقِينَ بِصِدْقِهِمْ وَيُعَذِّبَ ٱلْمُنَٰفِقِينَ إِن شَآءَ أَوْ يَتُوبَ عَلَيْهِمْ ۚ إِنَّ ٱللَّهَ كَانَ غَفُورًۭا رَّحِيمًۭا','أَوْ','["أَنِ","أَمْ","أَوْ","أَمِ"]'::jsonb,'أَوْ','very_hard',74,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3557.mp3',3557,NULL,TRUE),
('38-8',38,'ص',8,'أَءُنزِلَ عَلَيْهِ ٱلذِّكْرُ مِنۢ بَيْنِنَا ۚ بَلْ هُمْ فِى شَكٍّۢ مِّن ذِكْرِى ۖ بَل لَّمَّا يَذُوقُوا۟ عَذَابِ','فِى','["إِن","فِى","أَن","بَل"]'::jsonb,'فِى','very_hard',74,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3978.mp3',3978,NULL,TRUE),
('40-8',40,'غافر',8,'رَبَّنَا وَأَدْخِلْهُمْ جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ','مِنْ','["أَنِ","مِنْ","أَمْ","أَمِ"]'::jsonb,'مِنْ','very_hard',74,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4141.mp3',4141,NULL,TRUE),
('41-31',41,'فصلت',31,'نَحْنُ أَوْلِيَآؤُكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْءَاخِرَةِ ۖ وَلَكُمْ فِيهَا مَا تَشْتَهِىٓ أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ','فِيهَا','["فِيهَا","أَبَآ","أَحَدٍ","أَتَىٰ"]'::jsonb,'فِيهَا','very_hard',75,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4249.mp3',4249,NULL,TRUE),
('43-20',43,'الزخرف',20,'وَقَالُوا۟ لَوْ شَآءَ ٱلرَّحْمَٰنُ مَا عَبَدْنَٰهُم ۗ مَّا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ ۖ إِنْ هُمْ إِلَّا يَخْرُصُونَ','لَهُم','["أَنَّ","لَهُم","أَلَا","أَنتَ"]'::jsonb,'لَهُم','very_hard',75,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4345.mp3',4345,NULL,TRUE),
('46-12',46,'الأحقاف',12,'وَمِن قَبْلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامًۭا وَرَحْمَةًۭ ۚ وَهَٰذَا كِتَٰبٌۭ مُّصَدِّقٌۭ لِّسَانًا عَرَبِيًّۭا لِّيُنذِرَ ٱلَّذِينَ ظَلَمُوا۟ وَبُشْرَىٰ لِلْمُحْسِنِينَ','مُّصَدِّقٌۭ','["ءَاتَىٰهُمُ","مُّصَدِّقٌۭ","ءَامَنُوٓا۟","ءَايَٰتُنَا"]'::jsonb,'مُّصَدِّقٌۭ','very_hard',75,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4522.mp3',4522,NULL,TRUE),
('55-33',55,'الرحمن',33,'يَٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ إِنِ ٱسْتَطَعْتُمْ أَن تَنفُذُوا۟ مِنْ أَقْطَارِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ فَٱنفُذُوا۟ ۚ لَا تَنفُذُونَ إِلَّا بِسُلْطَٰنٍۢ','أَقْطَارِ','["ءَالَآءَ","ءَامِنًۭا","ءَايَٰتٌۭ","أَقْطَارِ"]'::jsonb,'أَقْطَارِ','very_hard',75,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4934.mp3',4934,NULL,TRUE),
('62-6',62,'الجمعة',6,'قُلْ يَٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓا۟ إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ','لِلَّهِ','["لِلَّهِ","ءَاسَىٰ","ءَادَمَ","ءَاخَرَ"]'::jsonb,'لِلَّهِ','very_hard',75,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5183.mp3',5183,NULL,TRUE),
('72-23',72,'الجن',23,'إِلَّا بَلَٰغًۭا مِّنَ ٱللَّهِ وَرِسَٰلَٰتِهِۦ ۚ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا','وَرَسُولَهُۥ','["ءَابَآؤُهُم","ءَابَآءَنَا","وَرَسُولَهُۥ","ءَايَٰتِهِۦٓ"]'::jsonb,'وَرَسُولَهُۥ','very_hard',75,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5470.mp3',5470,NULL,TRUE),
('2-97',2,'البقرة',97,'قُلْ مَن كَانَ عَدُوًّۭا لِّجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلْبِكَ بِإِذْنِ ٱللَّهِ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ وَهُدًۭى وَبُشْرَىٰ لِلْمُؤْمِنِينَ','بِإِذْنِ','["بِإِذْنِ","ءَاتِنَا","ءَاوَىٰٓ","ءَايَةًۭ"]'::jsonb,'بِإِذْنِ','very_hard',75,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/104.mp3',104,NULL,TRUE),
('2-279',2,'البقرة',279,'فَإِن لَّمْ تَفْعَلُوا۟ فَأْذَنُوا۟ بِحَرْبٍۢ مِّنَ ٱللَّهِ وَرَسُولِهِۦ ۖ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَٰلِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ','وَإِن','["وَإِن","أَنتَ","أَنَّ","أَلَا"]'::jsonb,'وَإِن','very_hard',75,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/286.mp3',286,NULL,TRUE),
('3-129',3,'آل عمران',129,'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ','لِمَن','["أَلَا","لِمَن","أَنَّ","أَنتَ"]'::jsonb,'لِمَن','very_hard',75,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/422.mp3',422,NULL,TRUE),
('4-144',4,'النساء',144,'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۚ أَتُرِيدُونَ أَن تَجْعَلُوا۟ لِلَّهِ عَلَيْكُمْ سُلْطَٰنًۭا مُّبِينًا','دُونِ','["أَنتَ","أَلَا","دُونِ","أَنَّ"]'::jsonb,'دُونِ','very_hard',75,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/637.mp3',637,NULL,TRUE),
('6-17',6,'الأنعام',17,'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّۢ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ ۖ وَإِن يَمْسَسْكَ بِخَيْرٍۢ فَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ','هُوَ','["هُوَ","أَنِ","أَمْ","أَمِ"]'::jsonb,'هُوَ','very_hard',76,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/806.mp3',806,NULL,TRUE),
('6-104',6,'الأنعام',104,'قَدْ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمْ ۖ فَمَنْ أَبْصَرَ فَلِنَفْسِهِۦ ۖ وَمَنْ عَمِىَ فَعَلَيْهَا ۚ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍۢ','فَلِنَفْسِهِۦ','["فَلِنَفْسِهِۦ","ءَابَآءَنَآ","ءَابَآؤُهُمْ","ءَابَآءَكُمْ"]'::jsonb,'فَلِنَفْسِهِۦ','very_hard',76,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/893.mp3',893,NULL,TRUE),
('7-95',7,'الأعراف',95,'ثُمَّ بَدَّلْنَا مَكَانَ ٱلسَّيِّئَةِ ٱلْحَسَنَةَ حَتَّىٰ عَفَوا۟ وَّقَالُوا۟ قَدْ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذْنَٰهُم بَغْتَةًۭ وَهُمْ لَا يَشْعُرُونَ','مَسَّ','["مَسَّ","أَلَا","أَنَّ","أَنتَ"]'::jsonb,'مَسَّ','very_hard',76,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1049.mp3',1049,NULL,TRUE),
('8-31',8,'الأنفال',31,'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا قَالُوا۟ قَدْ سَمِعْنَا لَوْ نَشَآءُ لَقُلْنَا مِثْلَ هَٰذَآ ۙ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ','نَشَآءُ','["ءَايَةًۭ","ءَاتِنَا","ءَاوَىٰٓ","نَشَآءُ"]'::jsonb,'نَشَآءُ','very_hard',76,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1191.mp3',1191,NULL,TRUE),
('9-90',9,'التوبة',90,'وَجَآءَ ٱلْمُعَذِّرُونَ مِنَ ٱلْأَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ ٱلَّذِينَ كَذَبُوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ سَيُصِيبُ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌۭ','كَذَبُوا۟','["ءَامِنًۭا","كَذَبُوا۟","ءَايَٰتٌۭ","ءَالَآءَ"]'::jsonb,'كَذَبُوا۟','very_hard',76,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1325.mp3',1325,NULL,TRUE),
('10-30',10,'يونس',30,'هُنَالِكَ تَبْلُوا۟ كُلُّ نَفْسٍۢ مَّآ أَسْلَفَتْ ۚ وَرُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ ۖ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ','ٱللَّهِ','["ٱللَّهِ","ءَاسَىٰ","ءَاخَرَ","ءَادَمَ"]'::jsonb,'ٱللَّهِ','very_hard',76,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1394.mp3',1394,NULL,TRUE),
('11-120',11,'هود',120,'وَكُلًّۭا نَّقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَ ۚ وَجَآءَكَ فِى هَٰذِهِ ٱلْحَقُّ وَمَوْعِظَةٌۭ وَذِكْرَىٰ لِلْمُؤْمِنِينَ','بِهِۦ','["أَنَّ","أَلَا","أَنتَ","بِهِۦ"]'::jsonb,'بِهِۦ','very_hard',76,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1593.mp3',1593,NULL,TRUE),
('13-41',13,'الرعد',41,'أَوَلَمْ يَرَوْا۟ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَا ۚ وَٱللَّهُ يَحْكُمُ لَا مُعَقِّبَ لِحُكْمِهِۦ ۚ وَهُوَ سَرِيعُ ٱلْحِسَابِ','وَٱللَّهُ','["ءَامِنًۭا","ءَالَآءَ","ءَايَٰتٌۭ","وَٱللَّهُ"]'::jsonb,'وَٱللَّهُ','very_hard',76,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1748.mp3',1748,NULL,TRUE),
('16-93',16,'النحل',93,'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةًۭ وَٰحِدَةًۭ وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَلَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَعْمَلُونَ','مَن','["بَل","أَن","مَن","إِن"]'::jsonb,'مَن','very_hard',76,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1994.mp3',1994,NULL,TRUE),
('17-70',17,'الإسراء',70,'۞ وَلَقَدْ كَرَّمْنَا بَنِىٓ ءَادَمَ وَحَمَلْنَٰهُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلْنَٰهُمْ عَلَىٰ كَثِيرٍۢ مِّمَّنْ خَلَقْنَا تَفْضِيلًۭا','وَرَزَقْنَٰهُم','["أَمَانِيُّهُمْ","أَبْلَغْتُكُمْ","أَفَبِنِعْمَةِ","وَرَزَقْنَٰهُم"]'::jsonb,'وَرَزَقْنَٰهُم','very_hard',76,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2099.mp3',2099,NULL,TRUE),
('20-69',20,'طه',69,'وَأَلْقِ مَا فِى يَمِينِكَ تَلْقَفْ مَا صَنَعُوٓا۟ ۖ إِنَّمَا صَنَعُوا۟ كَيْدُ سَٰحِرٍۢ ۖ وَلَا يُفْلِحُ ٱلسَّاحِرُ حَيْثُ أَتَىٰ','صَنَعُوا۟','["ءَامِنًۭا","ءَالَآءَ","ءَايَٰتٌۭ","صَنَعُوا۟"]'::jsonb,'صَنَعُوا۟','very_hard',77,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2417.mp3',2417,NULL,TRUE),
('22-60',22,'الحج',60,'۞ ذَٰلِكَ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِىَ عَلَيْهِ لَيَنصُرَنَّهُ ٱللَّهُ ۗ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌۭ','بُغِىَ','["أَحَدٍ","أَبَآ","أَتَىٰ","بُغِىَ"]'::jsonb,'بُغِىَ','very_hard',77,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2655.mp3',2655,NULL,TRUE),
('25-59',25,'الفرقان',59,'ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍۢ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۚ ٱلرَّحْمَٰنُ فَسْـَٔلْ بِهِۦ خَبِيرًۭا','أَيَّامٍۢ','["ءَايَٰتٌۭ","أَيَّامٍۢ","ءَالَآءَ","ءَامِنًۭا"]'::jsonb,'أَيَّامٍۢ','very_hard',77,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2914.mp3',2914,NULL,TRUE),
('29-22',29,'العنكبوت',22,'وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ ۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّۢ وَلَا نَصِيرٍۢ','وَمَا','["وَمَا","أَنَّ","أَنتَ","أَلَا"]'::jsonb,'وَمَا','very_hard',77,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3362.mp3',3362,NULL,TRUE),
('30-38',30,'الروم',38,'فَـَٔاتِ ذَا ٱلْقُرْبَىٰ حَقَّهُۥ وَٱلْمِسْكِينَ وَٱبْنَ ٱلسَّبِيلِ ۚ ذَٰلِكَ خَيْرٌۭ لِّلَّذِينَ يُرِيدُونَ وَجْهَ ٱللَّهِ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ','خَيْرٌۭ','["خَيْرٌۭ","ءَادَمَ","ءَاخَرَ","ءَاسَىٰ"]'::jsonb,'خَيْرٌۭ','very_hard',77,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3447.mp3',3447,NULL,TRUE),
('33-40',33,'الأحزاب',40,'مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٍۢ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّۦنَ ۗ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًۭا','رَّسُولَ','["ءَايَةًۭ","ءَاوَىٰٓ","ءَاتِنَا","رَّسُولَ"]'::jsonb,'رَّسُولَ','very_hard',77,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3573.mp3',3573,NULL,TRUE),
('38-27',38,'ص',27,'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا بَٰطِلًۭا ۚ ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُوا۟ ۚ فَوَيْلٌۭ لِّلَّذِينَ كَفَرُوا۟ مِنَ ٱلنَّارِ','ظَنُّ','["أَنَّ","ظَنُّ","أَنتَ","أَلَا"]'::jsonb,'ظَنُّ','very_hard',77,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3997.mp3',3997,NULL,TRUE),
('41-34',41,'فصلت',34,'وَلَا تَسْتَوِى ٱلْحَسَنَةُ وَلَا ٱلسَّيِّئَةُ ۚ ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ فَإِذَا ٱلَّذِى بَيْنَكَ وَبَيْنَهُۥ عَدَٰوَةٌۭ كَأَنَّهُۥ وَلِىٌّ حَمِيمٌۭ','أَحْسَنُ','["ءَايَةًۭ","ءَاوَىٰٓ","ءَاتِنَا","أَحْسَنُ"]'::jsonb,'أَحْسَنُ','very_hard',77,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4252.mp3',4252,NULL,TRUE),
('45-21',45,'الجاثية',21,'أَمْ حَسِبَ ٱلَّذِينَ ٱجْتَرَحُوا۟ ٱلسَّيِّـَٔاتِ أَن نَّجْعَلَهُمْ كَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَوَآءًۭ مَّحْيَاهُمْ وَمَمَاتُهُمْ ۚ سَآءَ مَا يَحْكُمُونَ','ءَامَنُوا۟','["ءَالِهَةًۭ","ءَامَنُوا۟","ءَاتَيْنَا","ءَامِنُوا۟"]'::jsonb,'ءَامَنُوا۟','very_hard',77,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4494.mp3',4494,NULL,TRUE),
('53-28',53,'النجم',28,'وَمَا لَهُم بِهِۦ مِنْ عِلْمٍ ۖ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ ۖ وَإِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًۭٔا','ٱلظَّنَّ','["ءَاوَىٰٓ","ٱلظَّنَّ","ءَايَةًۭ","ءَاتِنَا"]'::jsonb,'ٱلظَّنَّ','very_hard',77,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4812.mp3',4812,NULL,TRUE),
('63-8',63,'المنافقون',8,'يَقُولُونَ لَئِن رَّجَعْنَآ إِلَى ٱلْمَدِينَةِ لَيُخْرِجَنَّ ٱلْأَعَزُّ مِنْهَا ٱلْأَذَلَّ ۚ وَلِلَّهِ ٱلْعِزَّةُ وَلِرَسُولِهِۦ وَلِلْمُؤْمِنِينَ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَعْلَمُونَ','ٱلْأَذَلَّ','["ءَامَنُوا۟","ءَاتَيْنَا","ٱلْأَذَلَّ","ءَالِهَةًۭ"]'::jsonb,'ٱلْأَذَلَّ','very_hard',78,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5196.mp3',5196,NULL,TRUE),
('71-1',71,'نوح',1,'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِنَّآ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَن يَأْتِيَهُمْ عَذَابٌ أَلِيمٌۭ','أَنْ','["أَنْ","أَمْ","أَمِ","أَنِ"]'::jsonb,'أَنْ','very_hard',78,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5420.mp3',5420,NULL,TRUE),
('2-110',2,'البقرة',110,'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍۢ تَجِدُوهُ عِندَ ٱللَّهِ ۗ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌۭ','خَيْرٍۢ','["ءَادَمَ","ءَاسَىٰ","ءَاخَرَ","خَيْرٍۢ"]'::jsonb,'خَيْرٍۢ','very_hard',78,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/117.mp3',117,NULL,TRUE),
('3-18',3,'آل عمران',18,'شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلْمَلَٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ قَآئِمًۢا بِٱلْقِسْطِ ۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ','ٱلْعِلْمِ','["ءَايَٰتٌۭ","ٱلْعِلْمِ","ءَامِنًۭا","ءَالَآءَ"]'::jsonb,'ٱلْعِلْمِ','very_hard',78,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/311.mp3',311,NULL,TRUE),
('4-2',4,'النساء',2,'وَءَاتُوا۟ ٱلْيَتَٰمَىٰٓ أَمْوَٰلَهُمْ ۖ وَلَا تَتَبَدَّلُوا۟ ٱلْخَبِيثَ بِٱلطَّيِّبِ ۖ وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَهُمْ إِلَىٰٓ أَمْوَٰلِكُمْ ۚ إِنَّهُۥ كَانَ حُوبًۭا كَبِيرًۭا','تَأْكُلُوٓا۟','["ءَابَآؤُهُم","ءَابَآءَنَا","ءَايَٰتِهِۦٓ","تَأْكُلُوٓا۟"]'::jsonb,'تَأْكُلُوٓا۟','very_hard',78,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/495.mp3',495,NULL,TRUE),
('4-146',4,'النساء',146,'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَٱعْتَصَمُوا۟ بِٱللَّهِ وَأَخْلَصُوا۟ دِينَهُمْ لِلَّهِ فَأُو۟لَٰٓئِكَ مَعَ ٱلْمُؤْمِنِينَ ۖ وَسَوْفَ يُؤْتِ ٱللَّهُ ٱلْمُؤْمِنِينَ أَجْرًا عَظِيمًۭا','فَأُو۟لَٰٓئِكَ','["أَبْلَغْتُكُمْ","أَفَبِنِعْمَةِ","فَأُو۟لَٰٓئِكَ","أَمَانِيُّهُمْ"]'::jsonb,'فَأُو۟لَٰٓئِكَ','very_hard',78,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/639.mp3',639,NULL,TRUE),
('6-102',6,'الأنعام',102,'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ ۖ لَآ إِلَٰهَ إِلَّا هُوَ ۖ خَٰلِقُ كُلِّ شَىْءٍۢ فَٱعْبُدُوهُ ۚ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ وَكِيلٌۭ','كُلِّ','["أَنَّ","أَنتَ","كُلِّ","أَلَا"]'::jsonb,'كُلِّ','very_hard',78,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/891.mp3',891,NULL,TRUE),
('7-105',7,'الأعراف',105,'حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ قَدْ جِئْتُكُم بِبَيِّنَةٍۢ مِّن رَّبِّكُمْ فَأَرْسِلْ مَعِىَ بَنِىٓ إِسْرَٰٓءِيلَ','قَدْ','["أَمْ","قَدْ","أَنِ","أَمِ"]'::jsonb,'قَدْ','very_hard',78,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1059.mp3',1059,NULL,TRUE),
('8-53',8,'الأنفال',53,'ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمْ يَكُ مُغَيِّرًۭا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ ۙ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ','قَوْمٍ','["قَوْمٍ","أَبَآ","أَتَىٰ","أَحَدٍ"]'::jsonb,'قَوْمٍ','very_hard',78,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1213.mp3',1213,NULL,TRUE),
('9-59',9,'التوبة',59,'وَلَوْ أَنَّهُمْ رَضُوا۟ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُوا۟ حَسْبُنَا ٱللَّهُ سَيُؤْتِينَا ٱللَّهُ مِن فَضْلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ','ٱللَّهُ','["ٱللَّهُ","ءَاخَرَ","ءَاسَىٰ","ءَادَمَ"]'::jsonb,'ٱللَّهُ','very_hard',78,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1294.mp3',1294,NULL,TRUE),
('10-13',10,'يونس',13,'وَلَقَدْ أَهْلَكْنَا ٱلْقُرُونَ مِن قَبْلِكُمْ لَمَّا ظَلَمُوا۟ ۙ وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ وَمَا كَانُوا۟ لِيُؤْمِنُوا۟ ۚ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ','رُسُلُهُم','["ءَالَآءَ","ءَايَٰتٌۭ","ءَامِنًۭا","رُسُلُهُم"]'::jsonb,'رُسُلُهُم','very_hard',79,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1377.mp3',1377,NULL,TRUE),
('11-34',11,'هود',34,'وَلَا يَنفَعُكُمْ نُصْحِىٓ إِنْ أَرَدتُّ أَنْ أَنصَحَ لَكُمْ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغْوِيَكُمْ ۚ هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَعُونَ','كَانَ','["كَانَ","أَلَا","أَنَّ","أَنتَ"]'::jsonb,'كَانَ','very_hard',79,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1507.mp3',1507,NULL,TRUE),
('11-70',11,'هود',70,'فَلَمَّا رَءَآ أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَةًۭ ۚ قَالُوا۟ لَا تَخَفْ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمِ لُوطٍۢ','خِيفَةًۭ','["خِيفَةًۭ","ءَايَةًۭ","ءَاتِنَا","ءَاوَىٰٓ"]'::jsonb,'خِيفَةًۭ','very_hard',79,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1543.mp3',1543,NULL,TRUE),
('13-13',13,'الرعد',13,'وَيُسَبِّحُ ٱلرَّعْدُ بِحَمْدِهِۦ وَٱلْمَلَٰٓئِكَةُ مِنْ خِيفَتِهِۦ وَيُرْسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمْ يُجَٰدِلُونَ فِى ٱللَّهِ وَهُوَ شَدِيدُ ٱلْمِحَالِ','بِهَا','["أَنَّ","أَنتَ","أَلَا","بِهَا"]'::jsonb,'بِهَا','very_hard',79,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/1720.mp3',1720,NULL,TRUE),
('16-101',16,'النحل',101,'وَإِذَا بَدَّلْنَآ ءَايَةًۭ مَّكَانَ ءَايَةٍۢ ۙ وَٱللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ قَالُوٓا۟ إِنَّمَآ أَنتَ مُفْتَرٍۭ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ','يُنَزِّلُ','["ءَالَآءَ","ءَامِنًۭا","يُنَزِّلُ","ءَايَٰتٌۭ"]'::jsonb,'يُنَزِّلُ','very_hard',79,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2002.mp3',2002,NULL,TRUE),
('17-58',17,'الإسراء',58,'وَإِن مِّن قَرْيَةٍ إِلَّا نَحْنُ مُهْلِكُوهَا قَبْلَ يَوْمِ ٱلْقِيَٰمَةِ أَوْ مُعَذِّبُوهَا عَذَابًۭا شَدِيدًۭا ۚ كَانَ ذَٰلِكَ فِى ٱلْكِتَٰبِ مَسْطُورًۭا','أَوْ','["أَمْ","أَنِ","أَمِ","أَوْ"]'::jsonb,'أَوْ','very_hard',79,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2087.mp3',2087,NULL,TRUE),
('18-55',18,'الكهف',55,'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰ وَيَسْتَغْفِرُوا۟ رَبَّهُمْ إِلَّآ أَن تَأْتِيَهُمْ سُنَّةُ ٱلْأَوَّلِينَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ قُبُلًۭا','رَبَّهُمْ','["رَبَّهُمْ","ءَايَٰتٌۭ","ءَامِنًۭا","ءَالَآءَ"]'::jsonb,'رَبَّهُمْ','very_hard',79,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2195.mp3',2195,NULL,TRUE),
('20-131',20,'طه',131,'وَلَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًۭا مِّنْهُمْ زَهْرَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا لِنَفْتِنَهُمْ فِيهِ ۚ وَرِزْقُ رَبِّكَ خَيْرٌۭ وَأَبْقَىٰ','زَهْرَةَ','["ءَاتِنَا","زَهْرَةَ","ءَاوَىٰٓ","ءَايَةًۭ"]'::jsonb,'زَهْرَةَ','very_hard',79,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2479.mp3',2479,NULL,TRUE),
('23-100',23,'المؤمنون',100,'لَعَلِّىٓ أَعْمَلُ صَٰلِحًۭا فِيمَا تَرَكْتُ ۚ كَلَّآ ۚ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَا ۖ وَمِن وَرَآئِهِم بَرْزَخٌ إِلَىٰ يَوْمِ يُبْعَثُونَ','هُوَ','["هُوَ","أَمْ","أَمِ","أَنِ"]'::jsonb,'هُوَ','very_hard',79,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2773.mp3',2773,NULL,TRUE),
('24-51',24,'النور',51,'إِنَّمَا كَانَ قَوْلَ ٱلْمُؤْمِنِينَ إِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُوا۟ سَمِعْنَا وَأَطَعْنَا ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ','لِيَحْكُمَ','["ءَامَنُوا۟","ءَاتَيْنَا","لِيَحْكُمَ","ءَالِهَةًۭ"]'::jsonb,'لِيَحْكُمَ','very_hard',79,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/2842.mp3',2842,NULL,TRUE),
('28-37',28,'القصص',37,'وَقَالَ مُوسَىٰ رَبِّىٓ أَعْلَمُ بِمَن جَآءَ بِٱلْهُدَىٰ مِنْ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِ ۖ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ','وَمَن','["أَنتَ","أَلَا","أَنَّ","وَمَن"]'::jsonb,'وَمَن','very_hard',80,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3289.mp3',3289,NULL,TRUE),
('30-47',30,'الروم',47,'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَٰتِ فَٱنتَقَمْنَا مِنَ ٱلَّذِينَ أَجْرَمُوا۟ ۖ وَكَانَ حَقًّا عَلَيْنَا نَصْرُ ٱلْمُؤْمِنِينَ','فَٱنتَقَمْنَا','["ءَابَآءَنَآ","ءَابَآؤُهُمْ","ءَابَآءَكُمْ","فَٱنتَقَمْنَا"]'::jsonb,'فَٱنتَقَمْنَا','very_hard',80,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3456.mp3',3456,NULL,TRUE),
('34-47',34,'سبأ',47,'قُلْ مَا سَأَلْتُكُم مِّنْ أَجْرٍۢ فَهُوَ لَكُمْ ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌۭ','أَجْرِىَ','["أَجْرِىَ","ءَاوَىٰٓ","ءَايَةًۭ","ءَاتِنَا"]'::jsonb,'أَجْرِىَ','very_hard',80,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/3653.mp3',3653,NULL,TRUE),
('40-50',40,'غافر',50,'قَالُوٓا۟ أَوَلَمْ تَكُ تَأْتِيكُمْ رُسُلُكُم بِٱلْبَيِّنَٰتِ ۖ قَالُوا۟ بَلَىٰ ۚ قَالُوا۟ فَٱدْعُوا۟ ۗ وَمَا دُعَٰٓؤُا۟ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ','قَالُوا۟','["ءَايَةًۭ","قَالُوا۟","ءَاوَىٰٓ","ءَاتِنَا"]'::jsonb,'قَالُوا۟','very_hard',80,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4183.mp3',4183,NULL,TRUE),
('46-16',46,'الأحقاف',16,'أُو۟لَٰٓئِكَ ٱلَّذِينَ نَتَقَبَّلُ عَنْهُمْ أَحْسَنَ مَا عَمِلُوا۟ وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمْ فِىٓ أَصْحَٰبِ ٱلْجَنَّةِ ۖ وَعْدَ ٱلصِّدْقِ ٱلَّذِى كَانُوا۟ يُوعَدُونَ','سَيِّـَٔاتِهِمْ','["أَغْرَقْنَٰهُمْ","أَغْوَيْنَٰهُمْ","بِأَفْوَٰهِهِمْ","سَيِّـَٔاتِهِمْ"]'::jsonb,'سَيِّـَٔاتِهِمْ','very_hard',80,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4526.mp3',4526,NULL,TRUE),
('47-3',47,'محمد',3,'ذَٰلِكَ بِأَنَّ ٱلَّذِينَ كَفَرُوا۟ ٱتَّبَعُوا۟ ٱلْبَٰطِلَ وَأَنَّ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّبَعُوا۟ ٱلْحَقَّ مِن رَّبِّهِمْ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ لِلنَّاسِ أَمْثَٰلَهُمْ','ٱتَّبَعُوا۟','["ءَاتَىٰهُمُ","ٱتَّبَعُوا۟","ءَامَنُوٓا۟","ءَايَٰتُنَا"]'::jsonb,'ٱتَّبَعُوا۟','very_hard',80,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/4548.mp3',4548,NULL,TRUE),
('59-18',59,'الحشر',18,'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلْتَنظُرْ نَفْسٌۭ مَّا قَدَّمَتْ لِغَدٍۢ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ','قَدَّمَتْ','["ءَايَٰتٌۭ","قَدَّمَتْ","ءَالَآءَ","ءَامِنًۭا"]'::jsonb,'قَدَّمَتْ','very_hard',80,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/5144.mp3',5144,NULL,TRUE),
('2-13',2,'البقرة',13,'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓا۟ أَنُؤْمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُ ۗ أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعْلَمُونَ','كَمَآ','["أَحَدٍ","كَمَآ","أَبَآ","أَتَىٰ"]'::jsonb,'كَمَآ','very_hard',80,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/20.mp3',20,NULL,TRUE),
('2-111',2,'البقرة',111,'وَقَالُوا۟ لَن يَدْخُلَ ٱلْجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوْ نَصَٰرَىٰ ۗ تِلْكَ أَمَانِيُّهُمْ ۗ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ إِن كُنتُمْ صَٰدِقِينَ','نَصَٰرَىٰ','["نَصَٰرَىٰ","ءَايَٰتٌۭ","ءَالَآءَ","ءَامِنًۭا"]'::jsonb,'نَصَٰرَىٰ','very_hard',80,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/118.mp3',118,NULL,TRUE),
('3-50',3,'آل عمران',50,'وَمُصَدِّقًۭا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَلِأُحِلَّ لَكُم بَعْضَ ٱلَّذِى حُرِّمَ عَلَيْكُمْ ۚ وَجِئْتُكُم بِـَٔايَةٍۢ مِّن رَّبِّكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ','ٱلَّذِى','["ءَاسَىٰ","ءَاخَرَ","ءَادَمَ","ٱلَّذِى"]'::jsonb,'ٱلَّذِى','very_hard',80,'https://cdn.islamic.network/quran/audio/128/ar.alafasy/343.mp3',343,NULL,TRUE)
